static int mk(const char*p){if(mkdir_one(p)==0||errno==EEXIST)return 0;return -1;}
static int paths(const char*root,const char*domain,uint64_t seq,char*dd,size_t dsz,char*vp,size_t vsz){char norm[254];if(!root||qrx_domain_normalize(domain,norm))return -1;if(snprintf(dd,dsz,"%s/%s",root,norm)>=(int)dsz)return -1;if(snprintf(vp,vsz,"%s/%llu.qrxsite",dd,(unsigned long long)seq)>=(int)vsz)return -1;return 0;}
int qrx_net_publisher_archive(const char*root,const QrxNetPublishedSite*s,QrxNetSiteVersion*out){if(!root||!s||!s->manifest.sequence)return -1;char dd[1024],vp[1024];if(paths(root,s->manifest.domain,s->manifest.sequence,dd,sizeof(dd),vp,sizeof(vp))||mk(root)||mk(dd))return -1;FILE*e=fopen(vp,"rb");if(e){fclose(e);return -1;}if(qrx_net_site_package_save(s,vp))return -1;if(out){memset(out,0,sizeof(*out));strcpy(out->domain,s->manifest.domain);out->sequence=s->manifest.sequence;if(qrx_net_site_manifest_hash(&s->manifest,out->manifest_root)){remove(vp);return -1;}strcpy(out->package_path,vp);}return 0;}
int qrx_net_publisher_load_version(const char*root,const char*domain,uint64_t seq,QrxNetPublishedSite*out){char dd[1024],vp[1024];if(!seq||paths(root,domain,seq,dd,sizeof(dd),vp,sizeof(vp)))return -1;return qrx_net_site_package_load(vp,out);}
#ifndef _WIN32
int qrx_net_publisher_list_versions(const char*root,const char*domain,QrxNetSiteVersionCallback cb,void*ctx){if(!cb)return -1;char dd[1024],dummy[1024],norm[254];if(qrx_domain_normalize(domain,norm)||paths(root,norm,1,dd,sizeof(dd),dummy,sizeof(dummy)))return -1;DIR*d=opendir(dd);if(!d)return -1;struct dirent*de;int rc=0;while((de=readdir(d))){char*end=NULL;unsigned long long seq=strtoull(de->d_name,&end,10);if(!seq||!end||strcmp(end,".qrxsite"))continue;QrxNetPublishedSite s;if(qrx_net_publisher_load_version(root,norm,(uint64_t)seq,&s))continue;QrxNetSiteVersion v;memset(&v,0,sizeof(v));strcpy(v.domain,norm);v.sequence=(uint64_t)seq;qrx_net_site_manifest_hash(&s.manifest,v.manifest_root);paths(root,norm,v.sequence,dd,sizeof(dd),v.package_path,sizeof(v.package_path));qrx_net_published_site_free(&s);if(cb(&v,ctx)){rc=-1;break;}}closedir(d);return rc;}
#else
int qrx_net_publisher_list_versions(const char*root,const char*domain,QrxNetSiteVersionCallback cb,void*ctx){(void)root;(void)domain;(void)cb;(void)ctx;return -1;}
#endif
int qrx_net_publisher_prepare_rollback(const char*root,const char*domain,uint64_t seq,QrxNetSiteVersion*out){if(!out)return -1;QrxNetPublishedSite s;if(qrx_net_publisher_load_version(root,domain,seq,&s))return -1;memset(out,0,sizeof(*out));strcpy(out->domain,s.manifest.domain);out->sequence=s.manifest.sequence;int rc=qrx_net_site_manifest_hash(&s.manifest,out->manifest_root);char dd[1024];if(!rc)rc=paths(root,out->domain,out->sequence,dd,sizeof(dd),out->package_path,sizeof(out->package_path));qrx_net_published_site_free(&s);return rc;}

