static int pub_contract_id(const char*owner,const QrxNetPublishJob*j,char out[129]){if(!owner||!*owner||!j||!j->domain[0]||!out)return-1;EVP_MD_CTX*c=EVP_MD_CTX_new();unsigned char h[32];unsigned z=0;static const char d[]="QRX-NET-HOST-CONTRACT-V1";int ok=c&&EVP_DigestInit_ex(c,EVP_sha3_256(),NULL)==1&&EVP_DigestUpdate(c,d,sizeof(d)-1)==1&&EVP_DigestUpdate(c,owner,strlen(owner))==1&&EVP_DigestUpdate(c,j->domain,strlen(j->domain))==1&&EVP_DigestUpdate(c,j->manifest_root,64)==1&&EVP_DigestFinal_ex(c,h,&z)==1&&z==32;EVP_MD_CTX_free(c);if(!ok)return-1;static const char*x="0123456789abcdef";char hx[65];for(int i=0;i<32;i++){hx[i*2]=x[h[i]>>4];hx[i*2+1]=x[h[i]&15];}hx[64]=0;snprintf(out,129,"web-%s",hx);return 0;}
static int pub_contract_matches(const QrxStorageContractState*c,const char*owner,const QrxNetPublishJob*j,const QrxDrivePreparedUpload*p,uint64_t rate){return !c||strcmp(c->owner,owner)||strcmp(c->profile,"STANDARD")||c->logical_bytes!=p->ciphertext_bytes||c->shard_bytes!=p->shard_bytes||c->shard_count!=p->total_shards||c->base_atoms_per_gib_epoch!=rate||CRYPTO_memcmp(c->manifest_root,j->manifest_root,64)?-1:0;}
int qrx_net_publisher_host_next_step(QrxDB*db,const char*owner,const QrxNetPublishJob*j,const QrxDrivePreparedUpload*p,uint64_t h,uint64_t epochs,uint64_t rate,QrxNetHostStep*out){if(!db||!owner||!*owner||!j||!p||!out||!h||strcmp(p->manifest.crypto_suite,QRX_DRIVE_SUITE_PUBLIC_SIGNED)||qrx_drive_prepared_upload_verify_files(p))return-1;if(!epochs)epochs=30;if(!rate)rate=10000;memset(out,0,sizeof(*out));out->required_active_shards=QRX_NET_SITE_STANDARD_ACTIVE_MIN;out->base_atoms_per_gib_epoch=rate;if(pub_contract_id(owner,j,out->contract_id))return-1;QrxStorageContractState c;if(qrx_storage_contract_get(db,out->contract_id,&c)){uint64_t atoms=0;if(qrx_drive_contract_quote(p,epochs,rate,&atoms)||epochs>UINT64_MAX/QRX_STORAGE_PROOF_WINDOW_BLOCKS)return-1;out->end_height=h+epochs*QRX_STORAGE_PROOF_WINDOW_BLOCKS;if(out->end_height<h)return-1;char mh[129];pub_hex64(j->manifest_root,mh);out->kind=QRX_NET_HOST_STEP_CREATE;snprintf(out->tx_type,sizeof(out->tx_type),"STORAGE_CONTRACT_CREATE");snprintf(out->to,sizeof(out->to),"%s",owner);out->amount_atoms=atoms;snprintf(out->payload,sizeof(out->payload),"contract_id=%s;profile=STANDARD;logical_bytes=%llu;end_height=%llu;base_atoms_per_gib_epoch=%llu;manifest_root_hex=%s",out->contract_id,(unsigned long long)p->ciphertext_bytes,(unsigned long long)out->end_height,(unsigned long long)rate,mh);return 0;}if(pub_contract_matches(&c,owner,j,p,rate))return-1;out->end_height=c.end_height;for(unsigned i=0;i<p->total_shards;i++){QrxStorageAssignmentRecord a;if(qrx_storage_assignment_get(db,out->contract_id,i,&a)==0){if(strcmp(a.object_id,p->shard_object_ids[i])||CRYPTO_memcmp(a.merkle_root,p->shard_merkle_roots[i],64)||a.leaf_count!=p->shard_leaf_counts[i])return-1;out->assignments_present++;if(a.state==QRX_ASSIGN_ACTIVE)out->active_shards++;continue;}char provider[129],mr[129];if(qrx_storage_assignment_provider_for_height(db,out->contract_id,p->shard_bytes,h+1,provider))return-1;pub_hex64(p->shard_merkle_roots[i],mr);out->kind=QRX_NET_HOST_STEP_ASSIGN;out->shard_index=i;snprintf(out->tx_type,sizeof(out->tx_type),"STORAGE_ASSIGN");snprintf(out->to,sizeof(out->to),"%s",provider);snprintf(out->payload,sizeof(out->payload),"contract_id=%s;shard_index=%u;object_id=%s;merkle_root_hex=%s;leaf_count=%llu",out->contract_id,i,p->shard_object_ids[i],mr,(unsigned long long)p->shard_leaf_counts[i]);return 0;}if(out->active_shards>=QRX_NET_SITE_STANDARD_ACTIVE_MIN){out->kind=QRX_NET_HOST_STEP_READY_ACTIVATE;snprintf(out->tx_type,sizeof(out->tx_type),"-");return 0;}out->kind=j->transfer_id[0]?QRX_NET_HOST_STEP_WAIT_ACTIVE:QRX_NET_HOST_STEP_READY_UPLOAD;snprintf(out->tx_type,sizeof(out->tx_type),"-");return 0;}
int qrx_net_publisher_refresh_storage(QrxDB*db,QrxNetPublishJob*j,const QrxDrivePreparedUpload*p){if(!db||!j||!p)return-1;char owner[160]={0};QrxStorageContractState c;if(!j->storage_contract_id[0]||qrx_storage_contract_get(db,j->storage_contract_id,&c))return-1;snprintf(owner,sizeof(owner),"%s",c.owner);if(pub_contract_matches(&c,owner,j,p,c.base_atoms_per_gib_epoch))return-1;uint32_t active=0;for(unsigned i=0;i<p->total_shards;i++){QrxStorageAssignmentRecord a;if(qrx_storage_assignment_get(db,j->storage_contract_id,i,&a))continue;if(strcmp(a.object_id,p->shard_object_ids[i])||CRYPTO_memcmp(a.merkle_root,p->shard_merkle_roots[i],64)||a.leaf_count!=p->shard_leaf_counts[i])return-1;if(a.state==QRX_ASSIGN_ACTIVE)active++;}j->active_shards=active;j->status=active>=j->required_active_shards?QRX_NET_PUBLISH_STATUS_READY_TO_ACTIVATE:QRX_NET_PUBLISH_STATUS_WAITING_STORAGE;return qrx_net_publisher_job_save(j);}

